cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int KH, int KW,
    int stride, int padding,
    int Hout, int Wout)
{
  constexpr int Threads    = 64;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 4;

  const int tid = threadIdx.x;
  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{}));

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, KH, KW),
      make_stride((int64_t)Cin * KH * KW, (int64_t)KH * KW, (int64_t)KW, Int<1>{}));

  // Shared memory for a chunk of weights: (CcPerBlock, Cin, KH, KW)
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(CcPerBlock, Cin, KH, KW),
      make_stride(Cin * KH * KW, KH * KW, KW, 1));

  const int weightCount = CcPerBlock * Cin * KH * KW;
  for (int idx = tid; idx < weightCount; idx += Threads) {
    int rem = idx;
    int kw = rem % KW; rem /= KW;
    int kh = rem % KH; rem /= KH;
    int ci = rem % Cin; rem /= Cin;
    int cc = rem;
    int c = c_base + cc;
    T val = T(0);
    if (c < Cout) {
      val = mW(c, ci, kh, kw);
    }
    sW(cc, ci, kh, kw) = val;
  }
  int p_last = p_block + PTile - 1;
  if (p_last > P_total - 1) p_last = P_total - 1;
  int oh_min = p_block / Wout;
  int oh_max = p_last / Wout;
  int ih_lo = oh_min * stride - padding;
  if (ih_lo < 0) ih_lo = 0;
  int ih_hi = oh_max * stride - padding + KH - 1;
  if (ih_hi > H - 1) ih_hi = H - 1;
  int tileH = ih_hi - ih_lo + 1;
  if (tileH < 1) tileH = 1;
  T* sX_ptr = sW_ptr + weightCount;
  auto sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Cin, tileH, Win),
      make_stride(tileH * Win, Win, 1));
  const int xCount = Cin * tileH * Win;
  for (int idx = tid; idx < xCount; idx += Threads) {
    int rem = idx;
    int w = rem % Win; rem /= Win;
    int th = rem % tileH; rem /= tileH;
    int ci = rem;
    int ih = ih_lo + th;
    sX(ci, th, w) = mX(ci, ih, w);
  }
  __syncthreads();

  int  p_idx[PVec];
  int  oh_arr[PVec];
  int  ow_arr[PVec];
  bool valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
      valid[i]  = true;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
      valid[i]  = false;
    }
  }

  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (B != nullptr && c < Cout) {
      bval = (float)B[c];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    if (!valid[i]) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int ci = 0; ci < Cin; ++ci) {
      for (int kh = 0; kh < KH; ++kh) {
        int ih = oh * stride - padding + kh;
        if ((unsigned)ih >= (unsigned)H) continue;

        for (int kw = 0; kw < KW; ++kw) {
          int iw = ow * stride - padding + kw;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)sX(ci, ih - ih_lo, iw);

          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            float wval = (float)sW(cc, ci, kh, kw);
            acc[cc][i] += xval * wval;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid[i]) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   c10::optional<torch::Tensor> bias,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must be [Cout, Cin, KH, KW]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  int64_t Cout = weight.size(0);
  TORCH_CHECK(weight.size(1) == Cin, "weight.size(1) must equal Cin");
  int64_t KH = weight.size(2);
  int64_t KW = weight.size(3);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - KH) / stride + 1;
  int64_t Wout = (Win + 2 * padding - KW) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 64;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 4;

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  const int64_t rowSpan = (PTile + Wout - 1) / Wout + 1;
  const int64_t tileH_max = rowSpan * stride + KH;
  const size_t smem_weight = (size_t)CcPerBlock * Cin * KH * KW * sizeof(float);
  const size_t smem_input  = (size_t)Cin * tileH_max * Win * sizeof(float);
  size_t smem_bytes = smem_weight + smem_input;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  int device = 0;
  cudaGetDevice(&device);
  int max_smem_optin = 0;
  cudaDeviceGetAttribute(&max_smem_optin,
                          cudaDevAttrMaxSharedMemoryPerBlockOptin,
                          device);
  TORCH_CHECK((size_t)smem_bytes <= (size_t)max_smem_optin,
      "conv2d_cute_forward: requested dynamic shared memory (", smem_bytes,
      " bytes) exceeds device opt-in limit (", max_smem_optin,
      " bytes). Reduce CcPerBlock/Threads tile parameters.");
  if (smem_bytes > 48 * 1024) {
    cudaError_t attrErr = cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
    TORCH_CHECK(attrErr == cudaSuccess,
        "Requested dynamic shared memory (", smem_bytes,
        " bytes) exceeds device limit: ", cudaGetErrorString(attrErr));
  }

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)KH, (int)KW,
      stride, padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = (11, 11)
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(torch.empty(
            self.out_channels, self.in_channels, self.kernel_size[0], self.kernel_size[1]))
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

